<script setup lang="ts">
import { uiText } from '@/i18n'

import { ref,onMounted,onBeforeUnmount } from 'vue'
import { request } from '@/api/client'
interface Plan {settings:{minutes:number;spreadDays:number;revision:number};studyDay:boolean;usedSeconds:number;remainingSeconds:number;backlog:number;steps:{name:string;count:number;seconds:number;url:string}[];explanation:string}
const plan=ref<Plan>(),minutes=ref(20),spread=ref(7),error=ref(''),busy=ref(false),edit=ref(false),controller=new AbortController()
async function load(){try{const p=await request<Plan>('/learning/plan',{signal:controller.signal});if(!controller.signal.aborted){plan.value=p;minutes.value=p.settings.minutes;spread.value=p.settings.spreadDays}}catch(e){if(!controller.signal.aborted)error.value=(e as Error).message}}
async function save(){if(busy.value||!plan.value)return;busy.value=true;error.value='';try{await request('/learning/plan',{method:'PUT',body:JSON.stringify({minutes:minutes.value,spreadDays:spread.value,revision:plan.value.settings.revision})});await load();edit.value=false}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
onMounted(load);onBeforeUnmount(()=>controller.abort())
</script>
<template><section class="daily-plan"><header><div><p class="page-kicker">AT YOUR PACE</p><h2>{{ uiText('今天的学习安排') }}</h2></div><button class="button" @click="edit=!edit">{{ uiText('调整时间') }}</button></header><p v-if="error" role="alert">{{ uiText(error) }} <button class="table-action" @click="load">{{ uiText('重新加载') }}</button></p><form v-if="edit&&plan" @submit.prevent="save"><label>{{ uiText('每天可用时间（分钟）') }}<input v-model.number="minutes" class="field-input" type="number" min="5" max="180" required/></label><label>{{ uiText('积压复习分摊天数') }}<input v-model.number="spread" class="field-input" type="number" min="1" max="14" required/></label><button class="button button--dark" :disabled="busy">{{ uiText('保存计划') }}</button></form><template v-if="plan"><p class="plan-summary">{{plan.settings.minutes}} {{ uiText('分钟目标 · 已记录') }} {{Math.floor(plan.usedSeconds/60)}} {{ uiText('分钟 ·') }} {{plan.backlog}} {{ uiText('项到期复习') }}</p><p class="research-hint">{{ uiText(plan.explanation) }}</p><div class="plan-steps"><RouterLink v-for="(step,i) in plan.steps" :key="step.name" :to="step.url"><small>0{{i+1}}</small><strong>{{ uiText(step.name) }}</strong><span>{{step.name==='阅读与整理'?'':step.count+' 项 · '}}{{ uiText('约') }} {{Math.ceil(step.seconds/60)}} {{ uiText('分钟') }}</span><b aria-hidden="true">↗</b></RouterLink></div><p v-if="!plan.steps.length" class="research-hint">{{ uiText('今天的时间安排已完成。已有学习入口仍可自由使用。') }}</p></template></section></template>
<style scoped>.daily-plan{border-top:1px solid var(--line);padding:30px 0}.daily-plan header{display:flex;justify-content:space-between;align-items:center}.daily-plan h2{font-size:24px;font-weight:500}.plan-summary{font-size:15px}.plan-steps{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:14px;margin-top:22px}.plan-steps a{position:relative;padding:22px;border:1px solid var(--line);border-radius:12px;text-decoration:none;transition:background .2s,border-color .2s}.plan-steps a:hover{background:var(--surface-soft);border-color:var(--green)}.plan-steps small,.plan-steps span{display:block;color:var(--muted);font-size:12px}.plan-steps strong{display:block;margin:12px 0;font-weight:500}.plan-steps b{position:absolute;right:18px;top:18px;font-weight:400}.daily-plan form{display:flex;gap:18px;align-items:end;margin:20px 0}.daily-plan label{font-size:13px}.daily-plan input{display:block;margin-top:8px;width:160px}</style>
